#![allow(unsafe_code, clippy::unwrap_used, clippy::expect_used)]

//! One real request over a real TLS connection.
//!
//! Everything else in `daemon::api` is tested at a seam: the parser over an
//! in-memory stream, the router over a constructed `Request`. This is the piece
//! that only a socket can check, so it wires the actual pieces together: a
//! certificate chain in lego's layout, `serve_connection` on one end, a rustls
//! client that verifies against the issuing CA on the other.
//!
//! The certificate is generated by `openssl` into a tempdir at test time rather
//! than committed, so this repository ships no private key. Without `openssl` on
//! `PATH` the test reports what it skipped instead of passing quietly.

#![cfg(unix)]

use super::*;

use std::io::{Read, Write};
use std::path::Path;
use std::process::Command;

use crate::daemon::api::devices::Tier;
use crate::daemon::api::panes::{HerdrOut, HerdrProbeOut, PaneProbe};
use crate::daemon::api::routes::ApiContext;
use crate::daemon::bridge::{Hub, Instance, PeerResolver};
use crate::profile::{AppConfig, AppState};
use crate::push::Trigger;
use crate::testutil::HomeSandbox;

const TOKEN: &str = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";

/// A client that trusts only the CA just generated, so a handshake succeeding
/// means the server really presented a chain back to it.
pub(crate) fn client_config(ca_crt: &Path) -> Option<std::sync::Arc<rustls::ClientConfig>> {
    use rustls::pki_types::CertificateDer;
    use rustls::pki_types::pem::PemObject;

    let mut roots = rustls::RootCertStore::empty();
    for cert in CertificateDer::pem_file_iter(ca_crt).ok()? {
        roots.add(cert.ok()?).ok()?;
    }
    let provider = std::sync::Arc::new(rustls::crypto::ring::default_provider());
    Some(std::sync::Arc::new(
        rustls::ClientConfig::builder_with_provider(provider)
            .with_safe_default_protocol_versions()
            .ok()?
            .with_root_certificates(roots)
            .with_no_client_auth(),
    ))
}

/// The device [`TOKEN`] authenticates as.
const DEVICE: &str = "tray";
/// The bearer of a view-only device, which the tests that need one pair.
const VIEW_TOKEN: &str = "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789";

fn empty_config() -> crate::profile::ConfigHandle {
    std::sync::Arc::new(crate::lockorder::RankedMutex::new(AppConfig {
        state: AppState::default(),
        profiles: Vec::new(),
    }))
}

/// A context with [`TOKEN`] paired as the control device [`DEVICE`].
fn ctx() -> std::sync::Arc<ApiContext> {
    ctx_with(crate::daemon::api::panes::absent_probe())
}

/// The same, with the caller's pane probe in place of the absent one.
fn ctx_with(herdr_probe: PaneProbe) -> std::sync::Arc<ApiContext> {
    crate::daemon::api::devices::seed_for_tests(DEVICE, Tier::Control, TOKEN)
        .expect("pair the fixture device");
    let status_path = crate::profile::clauth_dir().unwrap().join("status.json");
    ApiContext::for_tests(empty_config(), status_path, None, herdr_probe)
}

/// The name the generated certificate is issued for, and the name the client
/// asks for. Not this host's real FQDN: the point is the handshake, not the
/// lookup that finds the file.
pub(crate) const SERVER_NAME: &str = "localhost";

fn openssl(args: &[&str]) -> bool {
    Command::new("openssl")
        .args(args)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|s| s.success())
}

/// Turns a missing `openssl` from a silent skip into a failure.
///
/// [`generate_chain`] is the only coverage the TLS listener has, and a skipped
/// test is indistinguishable from a passing one in a summary line — so an image
/// that lost `openssl` would report green over an entirely untested listener,
/// indefinitely, with nothing to notice. CI sets this on the platforms whose
/// images carry `openssl`; a developer box without it still runs the rest of the
/// suite, and now says on stderr which tests it did not run.
const REQUIRE_TLS_FIXTURE_ENV: &str = "CLAUTH_REQUIRE_TLS_FIXTURE";

/// Announce — or refuse — a run with no `openssl` to build certificates with.
fn no_tls_fixture() {
    assert!(
        std::env::var(REQUIRE_TLS_FIXTURE_ENV).as_deref() != Ok("1"),
        "`openssl` is not on PATH and {REQUIRE_TLS_FIXTURE_ENV}=1. Every TLS test would \
         have been skipped, and a skip is indistinguishable from a pass — which is exactly \
         what this variable exists to catch. Install openssl, or unset the variable to \
         accept an untested TLS listener on this machine"
    );
    crate::logline::logline!(
        "clauth tests: `openssl` is not on PATH — SKIPPING every test that needs a \
         certificate, which is all TLS coverage there is. Set {REQUIRE_TLS_FIXTURE_ENV}=1 \
         to make this a failure instead"
    );
}

/// A CA, and a `localhost` certificate signed by it, laid out the way lego
/// writes them. `Err` when `openssl` is missing AND the run demands a fixture;
/// `Ok(None)` only for a missing `openssl` on a box that accepted the skip.
///
/// A present-but-failing `openssl` is an `Err` too, not a skip: a build that
/// rejects one of the generation flags is exactly that case, and a leg that
/// CI marks as required was silently carrying zero listener coverage while
/// reporting green — a skipped test is indistinguishable from a passing one
/// in a summary line.
pub(crate) fn generate_chain(
    dir: &Path,
) -> Result<Option<(crate::daemon::api::tls::CertPaths, std::path::PathBuf)>, String> {
    generate_chain_covering(dir, SERVER_NAME)
}

/// [`generate_chain`] for a leaf whose DNS name is `name` instead of
/// `localhost`. The files keep the `localhost` names, so a test can drive the
/// name a certificate carries apart from the name the file carrying it has.
fn generate_chain_covering(
    dir: &Path,
    name: &str,
) -> Result<Option<(crate::daemon::api::tls::CertPaths, std::path::PathBuf)>, String> {
    generate_chain_covering_names(dir, &[name])
}

/// [`generate_chain_covering`] for a leaf carrying every name in `names`, in
/// the order given and no others, so a test can make the certificate's own
/// names disagree with the name its file carries.
fn generate_chain_covering_names(
    dir: &Path,
    names: &[&str],
) -> Result<Option<(crate::daemon::api::tls::CertPaths, std::path::PathBuf)>, String> {
    // Checked up front and separately from the generation below, so "no openssl
    // here" (a skip) is never confused with "openssl is present and failing" (a
    // broken fixture, which errors below).
    if !openssl(&["version"]) {
        no_tls_fixture();
        return Ok(None);
    }
    let cn = names
        .first()
        .copied()
        .ok_or_else(|| "a certificate fixture needs at least one DNS name".to_string())?;

    let ca_key = dir.join("ca.key");
    let ca_crt = dir.join("ca.crt");
    let csr = dir.join("server.csr");
    let ext = dir.join("leaf.ext");
    let paths = crate::daemon::api::tls::lego_paths_in(dir, SERVER_NAME);

    let alt_names = names
        .iter()
        .map(|name| format!("DNS:{name}"))
        .collect::<Vec<_>>()
        .join(",");
    let write_ext = std::fs::write(
        &ext,
        format!("subjectAltName={alt_names}\nbasicConstraints=critical,CA:FALSE\n"),
    );
    if let Err(e) = write_ext {
        return Err(format!("failed to write the leaf extension file: {e}"));
    }
    // Keys are generated by `ecparam` + `pkey`, never `req -newkey`: LibreSSL
    // 3.3.6 (macOS's system `openssl` over a non-login shell) writes `req
    // -newkey ec -pkeyopt ec_paramgen_curve:P-256` keys with the curve as
    // EXPLICIT parameters — no `-newkey` spelling on it yields a named curve —
    // and rustls/ring refuse to parse such a key. OpenSSL ≥1.1 accepts these
    // flags too and writes named-curve keys either way, so this is the shape
    // both parsers take. SEC1 from `ecparam`, wrapped to PKCS#8 by `pkey`.
    let gen_key = |out: &Path| -> Result<(), String> {
        // One retry: `ecparam`/`pkey` were measured (on a macOS host,
        // 2026-09-10) exiting 1 with empty stderr roughly once per ten loaded
        // full-suite runs — only inside the test harness, never in 900
        // shell-level spawns — so a transient is masked rather than reported
        // as a product failure.
        let mut err = String::new();
        for _ in 0..2 {
            let raw = out.with_extension("sec1");
            let gen_args = [
                "ecparam",
                "-name",
                "prime256v1",
                "-param_enc",
                "named_curve",
                "-genkey",
                "-out",
                raw.to_str().ok_or("key path is not UTF-8")?,
            ];
            let wrap = [
                "pkey",
                "-in",
                raw.to_str().ok_or("key path is not UTF-8")?,
                "-out",
                out.to_str().ok_or("key path is not UTF-8")?,
            ];
            if !openssl(&gen_args) {
                err = "openssl failed to generate a named-curve key".to_string();
                continue;
            }
            if !openssl(&wrap) {
                err = "openssl failed to wrap the key as PKCS#8".to_string();
                continue;
            }
            return Ok(());
        }
        Err(err)
    };
    gen_key(&ca_key)?;
    gen_key(&paths.key)?;
    let ca_args = [
        "req",
        // `-new` is spelled out because LibreSSL 3.3.6's `req -x509 -key` does
        // not imply it (OpenSSL's does): without it req tries to read a CSR
        // from stdin and dies. `req -new -x509 -key` works on both.
        "-new",
        "-x509",
        "-key",
        ca_key.to_str().ok_or("ca key path is not UTF-8")?,
        "-out",
        ca_crt.to_str().ok_or("ca crt path is not UTF-8")?,
        "-days",
        "3650",
        "-subj",
        "/CN=clauth-test-ca",
        "-addext",
        "basicConstraints=critical,CA:TRUE",
    ];
    let leaf_args = [
        "req",
        "-new",
        "-key",
        paths.key.to_str().ok_or("leaf key path is not UTF-8")?,
        "-out",
        csr.to_str().ok_or("csr path is not UTF-8")?,
        "-subj",
        &format!("/CN={cn}"),
    ];
    let sign_args = [
        "x509",
        "-req",
        "-in",
        csr.to_str().ok_or("csr path is not UTF-8")?,
        "-CA",
        ca_crt.to_str().ok_or("ca crt path is not UTF-8")?,
        "-CAkey",
        ca_key.to_str().ok_or("ca key path is not UTF-8")?,
        "-out",
        paths.cert.to_str().ok_or("leaf crt path is not UTF-8")?,
        "-days",
        "3650",
        // LibreSSL (macOS's system `openssl`) predates the ≥1.1 auto-serial:
        // without an explicit serial it requires a `<CA>.srl` beside the CA,
        // deriving that path by cutting the CA path at its first dot — which a
        // `tempfile` dotdir pushes outside the tempdir. OpenSSL ≥1.1 accepts
        // this flag too, so it is unconditional.
        "-set_serial",
        "0x1",
        // LibreSSL 3.3.6 signs an EC leaf with ecdsa-with-SHA1 by default,
        // which rustls/webpki reject; SHA-256 is OpenSSL 1.1+'s default, so
        // spelling it out is a no-op there and the fix here.
        "-sha256",
        "-extfile",
        ext.to_str().ok_or("leaf ext path is not UTF-8")?,
    ];
    if !openssl(&ca_args) {
        return Err("openssl failed to self-sign the test CA".to_string());
    }
    if !openssl(&leaf_args) {
        return Err("openssl failed to produce the test leaf CSR".to_string());
    }
    if !openssl(&sign_args) {
        return Err("openssl failed to sign the test leaf".to_string());
    }
    // lego's `<fqdn>.issuer.crt`: the chain the leaf does not carry itself.
    let issuer = paths
        .issuer
        .as_deref()
        .ok_or_else(|| "no issuer path for the lego layout".to_string())?;
    std::fs::copy(&ca_crt, issuer).map_err(|e| format!("failed to copy the issuer chain: {e}"))?;
    Ok(Some((paths, ca_crt)))
}

/// A present-but-failing `openssl` must fail the run, not skip it. The missing
/// case is covered by `no_tls_fixture` + `CLAUTH_REQUIRE_TLS_FIXTURE`; the
/// FAILING case is the one CI's required legs were silently passing on — a
/// generation failure reports green over zero listener coverage.
///
/// A fake `openssl` that answers `version` (so the presence probe passes) and
/// fails everything else stands in for exactly that box.
#[test]
fn a_present_but_failing_openssl_fails_the_fixture_not_the_skip() {
    let _home = HomeSandbox::new();
    let tmp = tempfile::tempdir_in(_home.home()).expect("shim dir");
    let shim = tmp.path().join("openssl");
    std::fs::write(&shim, "#!/bin/sh\n[ \"$1\" = version ] && exit 0\nexit 1\n")
        .expect("write shim");
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = std::fs::metadata(&shim).expect("shim meta").permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(&shim, perms).expect("chmod shim");
    }
    // SAFETY: env mutation is unsafe in Rust 2024; serialized by the sandbox's
    // HOME_TEST_LOCK, restored below.
    unsafe {
        let prev_path = std::env::var_os("PATH").expect("PATH is set");
        let mut path = std::ffi::OsString::from(tmp.path());
        path.push(":");
        path.push(&prev_path);
        std::env::set_var("PATH", path);
        let result = generate_chain(tmp.path());
        std::env::set_var("PATH", prev_path);
        let Err(msg) = result else {
            panic!("a failing openssl must error the fixture, not skip it");
        };
        assert!(
            msg.contains("openssl failed"),
            "the failure names its cause: {msg}"
        );
    }
}

/// A TLS client connection that can be driven request by request.
///
/// Responses are framed by their `Content-Length` rather than by reading to end
/// of stream, which is the whole point: on a persistent connection there is no
/// close to read to, and finding where one response stops is exactly what a
/// client has to do to reuse the connection.
struct Session {
    stream: rustls::StreamOwned<rustls::ClientConnection, std::net::TcpStream>,
    buf: Vec<u8>,
}

impl Session {
    fn connect(port: u16, client: &std::sync::Arc<rustls::ClientConfig>) -> std::io::Result<Self> {
        let name = rustls::pki_types::ServerName::try_from(SERVER_NAME)
            .map_err(std::io::Error::other)?
            .to_owned();
        let conn = rustls::ClientConnection::new(std::sync::Arc::clone(client), name)
            .map_err(std::io::Error::other)?;
        let sock = std::net::TcpStream::connect(("127.0.0.1", port))?;
        sock.set_read_timeout(Some(std::time::Duration::from_secs(10)))?;
        Ok(Self {
            stream: rustls::StreamOwned::new(conn, sock),
            buf: Vec::new(),
        })
    }

    fn send(&mut self, request: &str) -> std::io::Result<()> {
        self.stream.write_all(request.as_bytes())?;
        self.stream.flush()
    }

    /// One response: its head, and its body of exactly `Content-Length` bytes.
    /// Anything already read past it stays buffered for the next call.
    fn recv(&mut self) -> std::io::Result<(String, String)> {
        let mut chunk = [0u8; 512];
        let head_end = loop {
            if let Some(i) = self.buf.windows(4).position(|w| w == b"\r\n\r\n") {
                break i + 4;
            }
            let n = self.stream.read(&mut chunk)?;
            if n == 0 {
                return Err(std::io::Error::other("eof before a response head"));
            }
            self.buf.extend_from_slice(&chunk[..n]);
        };
        let head = String::from_utf8_lossy(&self.buf[..head_end]).into_owned();
        let len: usize = head
            .lines()
            .find_map(|line| {
                let (name, value) = line.split_once(':')?;
                name.eq_ignore_ascii_case("content-length")
                    .then(|| value.trim().parse().ok())?
            })
            .ok_or_else(|| std::io::Error::other("response has no Content-Length"))?;
        while self.buf.len() < head_end + len {
            let n = self.stream.read(&mut chunk)?;
            if n == 0 {
                return Err(std::io::Error::other("eof before a response body"));
            }
            self.buf.extend_from_slice(&chunk[..n]);
        }
        let body = String::from_utf8_lossy(&self.buf[head_end..head_end + len]).into_owned();
        self.buf.drain(..head_end + len);
        Ok((head, body))
    }
}

/// One request on its own connection, for the cases that end in a close.
fn round_trip(
    port: u16,
    client: &std::sync::Arc<rustls::ClientConfig>,
    request: &str,
) -> std::io::Result<String> {
    let mut session = Session::connect(port, client)?;
    session.send(request)?;
    let (head, body) = session.recv()?;
    Ok(format!("{head}{body}"))
}

#[test]
fn a_real_tls_request_is_served_end_to_end() {
    let dir = tempfile::tempdir().expect("tempdir");
    let Some((paths, ca_crt)) = generate_chain(dir.path()).expect("fixture") else {
        eprintln!("SKIPPED a_real_tls_request_is_served_end_to_end: openssl is not usable here");
        return;
    };
    let server_tls = tls::server_config_from(&paths).expect("server config");
    let Some(client_tls) = client_config(&ca_crt) else {
        eprintln!("SKIPPED a_real_tls_request_is_served_end_to_end: client config");
        return;
    };

    let home = HomeSandbox::new();
    let ctx = ctx();
    let feed = r#"{"schema":1,"active_profile":"alpha","profiles":[]}"#;
    crate::profile::mkdir_700(&crate::profile::clauth_dir().unwrap()).expect("mkdir");
    std::fs::write(&ctx.status_path, feed).expect("seed feed");

    let listener = std::net::TcpListener::bind(("127.0.0.1", 0)).expect("bind");
    let port = listener.local_addr().expect("addr").port();

    // Three connections, served one at a time on a worker thread: the
    // authenticated read, an unauthenticated one, and a request for a path that
    // does not exist.
    std::thread::scope(|scope| {
        scope.spawn(|| {
            for _ in 0..3 {
                let (stream, peer) = listener.accept().expect("accept");
                serve_connection(stream, peer, &server_tls, &ctx, Limits::DEFAULT);
            }
        });

        let authorized = round_trip(
            port,
            &client_tls,
            &format!(
                "GET /api/v1/status HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("authorized round trip");
        assert!(
            authorized.starts_with("HTTP/1.1 200 OK\r\n"),
            "{authorized}"
        );
        assert!(
            authorized.ends_with(feed),
            "the published feed must arrive intact over TLS: {authorized}"
        );

        let anonymous = round_trip(
            port,
            &client_tls,
            &format!(
                "GET /api/v1/status HTTP/1.1\r\nHost: {SERVER_NAME}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("anonymous round trip");
        assert!(
            anonymous.starts_with("HTTP/1.1 401 Unauthorized\r\n"),
            "{anonymous}"
        );
        assert!(
            !anonymous.contains("active_profile"),
            "an unauthenticated caller must learn no account names: {anonymous}"
        );

        let missing = round_trip(
            port,
            &client_tls,
            &format!(
                "GET /api/v1/nope HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("404 round trip");
        assert!(
            missing.starts_with("HTTP/1.1 404 Not Found\r\n"),
            "{missing}"
        );
    });

    drop(home);
}

/// The per-request log line is what an unauthenticated peer can fill: the 401
/// is logged for peers that never presented a credential, and a request path is
/// bounded only by the 8 KiB header limit. The connection handler runs on the
/// worker thread this closure IS, so the logline capture installs there and the
/// real served line lands in the buffer.
#[test]
fn the_log_line_for_a_long_unauthenticated_path_is_bounded() {
    let Some(fx) = fixture() else {
        eprintln!(
            "SKIPPED the_log_line_for_a_long_unauthenticated_path_is_bounded: \
             openssl is not usable here"
        );
        return;
    };
    let Fixture {
        port,
        listener,
        server_tls,
        client_tls,
        ctx,
        feed: _feed,
        _home,
        _dir,
    } = fx;

    // Both wire fields flood: the method is raw bytes httparse never length-
    // checks, and the path/query split means a flood can ride either. One
    // request carrying a long METHOD and a long bare PATH (no `?`) catches a
    // bound that covers only one of them.
    let method = "B".repeat(2048);
    let path = format!("/{}", "A".repeat(2048));
    let lines = crate::logline::LogLines::new();
    let worker_lines = lines.clone();
    std::thread::scope(|scope| {
        scope.spawn(move || {
            let _capture = worker_lines.capture_here();
            let (stream, peer) = listener.accept().expect("accept");
            serve_connection(stream, peer, &server_tls, &ctx, Limits::DEFAULT);
        });

        let anonymous = round_trip(
            port,
            &client_tls,
            &format!(
                "{method} {path} HTTP/1.1\r\nHost: {SERVER_NAME}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("anonymous round trip");
        assert!(
            anonymous.starts_with("HTTP/1.1 401 Unauthorized\r\n"),
            "{anonymous}"
        );
    });

    // "clauth api: " (12) + a peer address (≤21) + " - " (3, no device) + the
    // summary (≤131: `http::LOG_TEXT_LIMIT` plus its "..." marker) + " -> 401"
    // (7).
    let bound = 12 + 21 + 3 + 131 + 7;
    let logged = lines.snapshot();
    let line = logged
        .iter()
        .find(|l| l.ends_with("-> 401"))
        .expect("the 401 line was logged");
    assert!(
        line.chars().count() <= bound,
        "a long unauthenticated path writes a bounded line: {} chars",
        line.chars().count()
    );
}

/// A test fixture's whole world: a certificate, a seeded feed, and a listener.
/// Returns the port plus everything the caller has to keep alive.
struct Fixture {
    port: u16,
    listener: std::net::TcpListener,
    server_tls: std::sync::Arc<rustls::ServerConfig>,
    client_tls: std::sync::Arc<rustls::ClientConfig>,
    ctx: std::sync::Arc<ApiContext>,
    feed: String,
    _home: HomeSandbox,
    _dir: tempfile::TempDir,
}

/// `None` when openssl cannot produce a certificate here.
fn fixture() -> Option<Fixture> {
    fixture_with(crate::daemon::api::panes::absent_probe())
}

/// [`fixture`] with the caller's pane probe in its context.
fn fixture_with(herdr_probe: PaneProbe) -> Option<Fixture> {
    let dir = tempfile::tempdir().expect("tempdir");
    let (paths, ca_crt) = generate_chain(dir.path()).expect("fixture")?;
    let server_tls = tls::server_config_from(&paths).expect("server config");
    let client_tls = client_config(&ca_crt)?;

    let home = HomeSandbox::new();
    let ctx = ctx_with(herdr_probe);
    let feed = r#"{"schema":1,"active_profile":"alpha","profiles":[]}"#.to_string();
    crate::profile::mkdir_700(&crate::profile::clauth_dir().unwrap()).expect("mkdir");
    std::fs::write(&ctx.status_path, &feed).expect("seed feed");

    let listener = std::net::TcpListener::bind(("127.0.0.1", 0)).expect("bind");
    let port = listener.local_addr().expect("addr").port();
    Some(Fixture {
        port,
        listener,
        server_tls,
        client_tls,
        ctx,
        feed,
        _home: home,
        _dir: dir,
    })
}

/// Relay `client -> upstream`, splitting each chunk in half with a pause
/// between the halves once `fragment` is set, so the server's read timeout
/// lands INSIDE a TLS record rather than on a record boundary. Returns the port
/// to point a client at.
///
/// Fragmentation is switched on rather than always-on because the handshake and
/// the first request share one budget (`io_timeout`); splitting those would
/// test the budget rather than the resumption this exists for.
///
/// Handles exactly one connection and stops when either side closes.
///
/// Runs on a detached thread holding only owned data. That is safe here where
/// it usually would not be: it never resolves a path or touches `~/.clauth`, so
/// it cannot outlive the test's `HomeSandbox` and reach the operator's real
/// tree. It ends when either side closes, or on its own read deadline.
fn fragmenting_proxy(
    upstream: u16,
    pause: std::time::Duration,
    fragment: std::sync::Arc<std::sync::atomic::AtomicBool>,
) -> u16 {
    let listener = std::net::TcpListener::bind(("127.0.0.1", 0)).expect("bind proxy");
    let port = listener.local_addr().expect("proxy addr").port();

    std::thread::spawn(move || {
        let (client, _) = listener.accept().expect("proxy accept");
        let server = std::net::TcpStream::connect(("127.0.0.1", upstream)).expect("proxy connect");
        let deadline = std::time::Duration::from_secs(20);
        client.set_read_timeout(Some(deadline)).ok();
        server.set_read_timeout(Some(deadline)).ok();

        let (mut c_read, mut c_write) = (
            client.try_clone().expect("clone client"),
            client.try_clone().expect("clone client"),
        );
        let (mut s_read, mut s_write) = (
            server.try_clone().expect("clone server"),
            server.try_clone().expect("clone server"),
        );

        std::thread::scope(|inner| {
            // Server to client: straight through.
            inner.spawn(move || {
                let mut buf = [0u8; 4096];
                while let Ok(n) = s_read.read(&mut buf) {
                    if n == 0 || c_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                let _ = c_write.shutdown(std::net::Shutdown::Write);
            });
            // Client to server: once armed, each chunk arrives as two pieces
            // with a gap between them.
            let mut buf = [0u8; 4096];
            while let Ok(n) = c_read.read(&mut buf) {
                if n == 0 {
                    break;
                }
                let split = if fragment.load(std::sync::atomic::Ordering::Acquire) {
                    (n / 2).max(1)
                } else {
                    n
                };
                if s_write.write_all(&buf[..split]).is_err() {
                    break;
                }
                let _ = s_write.flush();
                if split < n {
                    std::thread::sleep(pause);
                    if s_write.write_all(&buf[split..n]).is_err() {
                        break;
                    }
                    let _ = s_write.flush();
                }
            }
            let _ = s_write.shutdown(std::net::Shutdown::Write);
        });
    });
    port
}

/// The subtle half of the fix: a read timeout can land part-way through a TLS
/// record, not just on a message boundary.
///
/// The retry has to resume from rustls's buffered partial record rather than
/// treating it as a failure. If it did not, a client whose packets fragment
/// (any real network) would fail even though it was sending normally.
///
/// Only the SECOND request is fragmented. The handshake and the first request
/// share one budget (`io_timeout`, the first-request deadline), so splitting
/// those across timeouts would exhaust that budget and test it rather than the
/// resumption this is about.
#[test]
fn a_read_timeout_inside_a_tls_record_resumes() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED a_read_timeout_inside_a_tls_record_resumes: openssl is not usable here");
        return;
    };
    // The pause between halves comfortably exceeds one io timeout, so the
    // record the server reads spans at least one timeout.
    let limits = Limits {
        io_timeout: std::time::Duration::from_millis(80),
        lifetime: std::time::Duration::from_secs(30),
        max_requests: 100,
    };
    let fragment = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, limits);
        });
        let proxy_port = fragmenting_proxy(
            f.port,
            std::time::Duration::from_millis(250),
            std::sync::Arc::clone(&fragment),
        );

        let get = format!(
            "GET /api/v1/status HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
             Authorization: Bearer {TOKEN}\r\n\r\n"
        );
        let mut session = Session::connect(proxy_port, &f.client_tls).expect("connect via proxy");

        // Handshake and first request unfragmented, so the connection is
        // established and on the generous idle budget.
        session.send(&get).expect("first send");
        let (head, _) = session.recv().expect("first recv");
        assert!(head.contains("Connection: keep-alive\r\n"), "{head}");

        // Now split every record across a read timeout.
        fragment.store(true, std::sync::atomic::Ordering::Release);
        session
            .send(&get)
            .expect("send through the fragmenting proxy");
        let (head, body) = session
            .recv()
            .expect("a record split across a read timeout must resume, not fail");
        assert!(head.starts_with("HTTP/1.1 200 OK\r\n"), "{head}");
        assert_eq!(body, f.feed);
    });
}

/// Three requests down ONE connection, each sent only after the previous
/// response was read. The TLS handshake happens once.
#[test]
fn a_connection_is_reused_across_requests() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED a_connection_is_reused_across_requests: openssl is not usable here");
        return;
    };

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, Limits::DEFAULT);
        });

        let mut session = Session::connect(f.port, &f.client_tls).expect("connect");
        for i in 0..3 {
            session
                .send(&format!(
                    "GET /api/v1/status HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                     Authorization: Bearer {TOKEN}\r\n\r\n"
                ))
                .unwrap_or_else(|e| panic!("send {i}: {e}"));
            let (head, body) = session.recv().unwrap_or_else(|e| panic!("recv {i}: {e}"));
            assert!(
                head.starts_with("HTTP/1.1 200 OK\r\n"),
                "request {i}: {head}"
            );
            assert!(
                head.contains("Connection: keep-alive\r\n"),
                "request {i} should have been told the connection survives: {head}"
            );
            assert!(head.contains("Keep-Alive: timeout="), "request {i}: {head}");
            assert_eq!(body, f.feed, "request {i}");
        }

        // Asking to close ends it, and the server says so on the way out.
        session
            .send(&format!(
                "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ))
            .expect("send close");
        let (head, _) = session.recv().expect("recv close");
        assert!(head.starts_with("HTTP/1.1 200 OK\r\n"), "{head}");
        assert!(head.contains("Connection: close\r\n"), "{head}");
    });
}

/// Two requests written in ONE call, before either response is read, and the
/// responses must come back in the order they were asked for.
#[test]
fn pipelined_requests_are_answered_in_order() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED pipelined_requests_are_answered_in_order: openssl is not usable here");
        return;
    };

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, Limits::DEFAULT);
        });

        let mut session = Session::connect(f.port, &f.client_tls).expect("connect");
        // The distinguishing move: both requests hit the wire together, so the
        // server reads the second out of the buffer left by the first.
        session
            .send(&format!(
                "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\n\r\n\
                 GET /api/v1/nope HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\n\r\n\
                 GET /api/v1/status HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ))
            .expect("send pipeline");

        let (first, first_body) = session.recv().expect("first response");
        assert!(first.starts_with("HTTP/1.1 200 OK\r\n"), "{first}");
        assert!(
            first_body.contains("\"schema\""),
            "the first response must be health's, not another route's: {first_body}"
        );

        let (second, _) = session.recv().expect("second response");
        assert!(
            second.starts_with("HTTP/1.1 404 Not Found\r\n"),
            "responses must not be reordered: {second}"
        );

        let (third, third_body) = session.recv().expect("third response");
        assert!(third.starts_with("HTTP/1.1 200 OK\r\n"), "{third}");
        assert_eq!(third_body, f.feed);
        assert!(
            third.contains("Connection: close\r\n"),
            "the last of the pipeline asked to close: {third}"
        );
    });
}

/// Short limits, so a whole connection lifecycle runs in milliseconds. The
/// ratios are what matter and they match production: an idle gap several times
/// the io timeout, well inside the lifetime.
fn brisk_limits() -> Limits {
    Limits {
        io_timeout: std::time::Duration::from_millis(150),
        lifetime: std::time::Duration::from_secs(30),
        max_requests: 100,
    }
}

/// The regression, end to end over TLS.
///
/// A client polling slower than the socket read timeout must still find its
/// connection alive. This is what was broken: the idle wait hit the 10s socket
/// timeout, the loop treated it as a failure, and every client polling slower
/// than 10s re-handshaked on every request while being told it had 120 seconds.
#[test]
fn a_connection_survives_an_idle_gap_longer_than_the_io_timeout() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED a_connection_survives_an_idle_gap: openssl is not usable here");
        return;
    };
    let limits = brisk_limits();

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, limits);
        });

        let mut session = Session::connect(f.port, &f.client_tls).expect("connect");
        let get = format!(
            "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
             Authorization: Bearer {TOKEN}\r\n\r\n"
        );

        session.send(&get).expect("first send");
        let (head, _) = session.recv().expect("first recv");
        assert!(head.contains("Connection: keep-alive\r\n"), "{head}");

        // Idle for several times the io timeout, the shape of a poll interval.
        std::thread::sleep(limits.io_timeout * 4);

        session
            .send(&get)
            .expect("the connection must survive an idle gap");
        let (head, _) = session
            .recv()
            .expect("a second request after idling must be answered on the same connection");
        assert!(head.starts_with("HTTP/1.1 200 OK\r\n"), "{head}");
        assert!(head.contains("Connection: keep-alive\r\n"), "{head}");
    });
}

/// The advertised budget is real in both directions: what a response promises
/// is what is left, and running out actually closes the connection.
#[test]
fn the_advertised_budget_is_the_one_enforced() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED the_advertised_budget_is_the_one_enforced: openssl is not usable here");
        return;
    };
    // A whole-second lifetime: `Keep-Alive: timeout=` is whole seconds, so a
    // sub-second budget can only ever be advertised as zero and the timeout
    // bound below degenerates into "advertised is zero".
    let limits = Limits {
        io_timeout: std::time::Duration::from_millis(100),
        lifetime: std::time::Duration::from_secs(2),
        max_requests: 100,
    };

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, limits);
        });

        let mut session = Session::connect(f.port, &f.client_tls).expect("connect");
        let get = format!(
            "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
             Authorization: Bearer {TOKEN}\r\n\r\n"
        );
        session.send(&get).expect("send");
        let (head, _) = session.recv().expect("recv");

        // What is advertised is what remains, so it can never exceed the budget
        // the connection was actually given.
        let (advertised, requests_left) = keep_alive_figures(&head);
        assert!(
            advertised <= limits.lifetime.as_secs(),
            "advertised {advertised}s but the connection only has {}s: {head}",
            limits.lifetime.as_secs()
        );

        // The remaining-request count is the other advertised figure, and it
        // must be the budget genuinely left — which means it decrements. Only
        // this read pins it; a response advertising a constant passes the
        // timeout bound alone.
        session.send(&get).expect("second send");
        let (head_two, _) = session.recv().expect("second recv");
        let (_, requests_left_two) = keep_alive_figures(&head_two);
        assert_eq!(
            (requests_left, requests_left_two),
            (
                u64::from(limits.max_requests - 1),
                u64::from(limits.max_requests - 2)
            ),
            "the advertised request budget is what is left, not a constant: {head}{head_two}"
        );

        // Idle past the whole budget: the connection must be gone, not lingering.
        std::thread::sleep(limits.lifetime + std::time::Duration::from_millis(300));
        let _ = session.send(&get);
        assert!(
            session.recv().is_err(),
            "a connection past its advertised budget must be closed"
        );
    });
}

/// The events stream is close-delimited: the head carries no `Content-Length`,
/// frames stream until the connection's short lifetime, and the TLS close
/// arrives cleanly so an `EventSource` sees an orderly end and reconnects.
#[test]
fn the_events_stream_runs_until_the_lifetime_and_closes_cleanly() {
    let Some(f) = fixture() else {
        eprintln!(
            "SKIPPED the_events_stream_runs_until_the_lifetime_and_closes_cleanly: openssl is not usable here"
        );
        return;
    };
    let limits = Limits {
        io_timeout: std::time::Duration::from_millis(200),
        lifetime: std::time::Duration::from_secs(1),
        max_requests: 100,
    };

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, limits);
        });

        let mut session = Session::connect(f.port, &f.client_tls).expect("connect");
        session
            .send(&format!(
                "GET /api/v1/events HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ))
            .expect("send");

        // A stream frames by close, not Content-Length, so read to end of
        // stream and let the server's close deliver the boundary.
        let mut all = Vec::new();
        let mut chunk = [0u8; 512];
        loop {
            match session.stream.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => all.extend_from_slice(&chunk[..n]),
                Err(e) => panic!("stream read failed: {e}"),
            }
        }
        let text = String::from_utf8_lossy(&all);
        assert!(text.starts_with("HTTP/1.1 200 OK\r\n"), "{text:?}");
        assert!(
            text.contains("Content-Type: text/event-stream\r\n"),
            "{text:?}"
        );
        assert!(!text.contains("Content-Length:"), "{text:?}");
        assert!(text.contains("Connection: close\r\n"), "{text:?}");
        assert!(text.contains("retry: 1000\n"), "{text:?}");
        assert!(text.contains("event: status\n"), "{text:?}");
    });
}

/// The `Keep-Alive: timeout=N, max=M` figures a kept-alive response advertises.
fn keep_alive_figures(head: &str) -> (u64, u64) {
    let line = head
        .lines()
        .find(|l| l.trim().to_ascii_lowercase().starts_with("keep-alive:"))
        .unwrap_or_else(|| panic!("no Keep-Alive header in {head}"));
    let figures = line.split_once(':').expect("the prefix was matched").1;
    let mut timeout = None;
    let mut max = None;
    for part in figures.split(',') {
        let part = part.trim();
        if let Some(v) = part.strip_prefix("timeout=") {
            timeout = v.trim().parse().ok();
        } else if let Some(v) = part.strip_prefix("max=") {
            max = v.trim().parse().ok();
        }
    }
    (
        timeout.unwrap_or_else(|| panic!("no timeout figure in {head}")),
        max.unwrap_or_else(|| panic!("no max figure in {head}")),
    )
}

